def transform(grid):
    from collections import Counter
    R, C = len(grid), len(grid[0])
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]
    cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] != bg]
    cs = set(cells)
    dirs = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if (dr, dc) != (0, 0)]

    def runs_for(r, c, dr, dc):
        r2, c2 = r + dr, c + dc
        if not (0 <= r2 < R and 0 <= c2 < C) or grid[r2][c2] != grid[r][c] or (r2, c2) not in cs:
            return None
        res = []
        for end, step in (((r2, c2), (dr, dc)), ((r, c), (-dr, -dc))):
            run = []
            rr, cc = end[0] + step[0], end[1] + step[1]
            while 0 <= rr < R and 0 <= cc < C and grid[rr][cc] == bg:
                run.append((rr, cc))
                rr += step[0]
                cc += step[1]
            res.append(run)
        return res

    for diag in (True, False):
        cand = []
        for (r, c) in cells:
            for dr, dc in dirs:
                if ((dr != 0 and dc != 0) != diag):
                    continue
                res = runs_for(r, c, dr, dc)
                if res is None:
                    continue
                for run in res:
                    if run:
                        cand.append((len(run), grid[r][c], run))
        if cand:
            cand.sort(key=lambda t: t[0])
            L, col, run = cand[0]
            out = [row[:] for row in grid]
            for rr, cc in run:
                out[rr][cc] = col
            return out
    return [row[:] for row in grid]
